/**
 * CommonJS run lock: one Playwright run per target environment and lane. Test repos opt in by
 * putting it first in `globalSetup`; Orca's launcher requires the same file. Dependency-free:
 * it runs inside the user's test repo.
 */
export function getOrcaPlaywrightLockSource(): string {
  return `'use strict'
// Generated by Orca. One Playwright run per target environment and lane.
const fs = require('node:fs')
const path = require('node:path')
const crypto = require('node:crypto')

const DEFAULT_POLL_MS = 2000
// Why: a lock file read between its creation and its first write looks empty.
const UNREADABLE_GRACE_MS = 5000

function read(source, name) {
  const value = source[name]
  return value ? value : null
}

function isAlive(pid) {
  try {
    process.kill(pid, 0)
    return true
  } catch (error) {
    return Boolean(error) && error.code === 'EPERM'
  }
}

function readTargets(dir) {
  try {
    return JSON.parse(fs.readFileSync(path.join(dir, 'targets.json'), 'utf8'))
  } catch {
    return {}
  }
}

function getLockKey(source) {
  source = source || process.env
  const dir = read(source, 'ORCA_TEST_RUNS_DIR')
  const worktreeId = read(source, 'ORCA_WORKTREE_ID')
  const devEnvId = dir && worktreeId ? readTargets(dir)[worktreeId] : null
  const target =
    read(source, 'ORCA_TEST_LOCK_KEY') ||
    (devEnvId ? 'dev-env:' + devEnvId : null) ||
    (worktreeId ? 'worktree:' + worktreeId : null) ||
    'cwd:' + process.cwd()
  return target + '#' + (read(source, 'ORCA_TEST_LOCK_SCOPE') || '')
}

function getTrigger(source) {
  if (read(source, 'ORCA_TEST_RUN_TRIGGER') === 'orca') return 'orca'
  const isAgent = ['ORCA_AGENT_LAUNCH', 'ORCA_AGENT_LAUNCH_TOKEN', 'CLAUDECODE', 'CODEX_THREAD_ID'].some(
    (name) => read(source, name)
  )
  return isAgent ? 'agent' : 'user'
}

function createAbortError() {
  const error = new Error('Stopped waiting for the test environment')
  error.name = 'AbortError'
  return error
}

function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(resolve, ms)
    if (signal) {
      signal.addEventListener('abort', () => {
        clearTimeout(timer)
        reject(createAbortError())
      }, { once: true })
    }
  })
}

function readHolder(file) {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'))
  } catch {
    return null
  }
}

function isStale(file, holder) {
  if (holder) return !isAlive(holder.pid)
  try {
    return Date.now() - fs.statSync(file).mtimeMs > UNREADABLE_GRACE_MS
  } catch {
    return true
  }
}

function hash(value) {
  return crypto.createHash('sha1').update(value).digest('hex')
}

function splitKey(key) {
  const index = key.lastIndexOf('#')
  return index === -1 ? [key, ''] : [key.slice(0, index), key.slice(index + 1)]
}

function removeStaleLocks(dir) {
  for (const name of fs.readdirSync(dir).filter((entry) => entry.endsWith('.json'))) {
    const file = path.join(dir, name)
    if (isStale(file, readHolder(file))) {
      try {
        fs.unlinkSync(file)
      } catch {}
    }
  }
}

/**
 * One lock folder per target; a lane locks its own files, a run without a lane the whole target.
 * Why one file per holder: a cleaner can only remove the exact file it judged stale.
 */
async function acquireLock(input) {
  const [target, scope] = splitKey(input.key)
  const dir = path.join(input.dir, 'locks', hash(target))
  fs.mkdirSync(dir, { recursive: true })
  const token = crypto.randomUUID()
  const prefix = scope ? 'lane-' + hash(scope).slice(0, 16) + '.' : '_all.'
  const ownName = prefix + token + '.json'
  const own = path.join(dir, ownName)
  const pollMs = input.pollMs || DEFAULT_POLL_MS
  let hasReportedWait = false
  const write = (holder) => {
    fs.writeFileSync(own + '.tmp', JSON.stringify({ ...holder, key: input.key, token }))
    fs.renameSync(own + '.tmp', own)
  }
  for (;;) {
    if (input.signal && input.signal.aborted) throw createAbortError()
    removeStaleLocks(dir)
    write(input.holder)
    const conflicts = fs
      .readdirSync(dir)
      .filter(
        (name) =>
          name !== ownName &&
          name.endsWith('.json') &&
          (!scope || name.startsWith(prefix) || name.startsWith('_all.'))
      )
    if (conflicts.length === 0) {
      const release = function release() {
        try {
          fs.unlinkSync(own)
        } catch {}
      }
      /** Hands the lock to the process that runs the tests, so it outlives the caller. */
      release.setHolderPid = (pid) => write({ ...input.holder, pid })
      return release
    }
    try {
      fs.unlinkSync(own)
    } catch {}
    const holder = readHolder(path.join(dir, conflicts[0]))
    if (holder && !hasReportedWait) {
      hasReportedWait = true
      if (input.onWait) input.onWait(holder)
    }
    // Why jitter: two runs that backed off from each other must not retry in lockstep.
    await sleep(pollMs + Math.floor(Math.random() * pollMs), input.signal)
  }
}

/** Playwright global setup: waits for the environment, returns the teardown that frees it. */
async function orcaRunLock() {
  const dir = read(process.env, 'ORCA_TEST_RUNS_DIR')
  if (!dir || read(process.env, 'ORCA_TEST_LOCK_HELD') === '1') return undefined
  const key = getLockKey(process.env)
  const release = await acquireLock({
    dir,
    key,
    holder: { pid: process.pid, trigger: getTrigger(process.env), label: key },
    onWait: (holder) =>
      process.stderr.write(
        '[orca] waiting for the ' + holder.trigger + ' run against ' + holder.label +
          ' (pid ' + holder.pid + ') to finish…\\n'
      )
  })
  // Why also on exit: a run stopped with Ctrl+C skips the teardown.
  process.once('exit', release)
  return async () => release()
}

module.exports = orcaRunLock
module.exports.getLockKey = getLockKey
module.exports.acquireLock = acquireLock
`
}
